package rs.unicredit.cardlifecycle.configuration;

import jakarta.persistence.AttributeConverter;
import org.jasypt.encryption.pbe.StandardPBEStringEncryptor;


public class StringCryptoConverterCustom implements AttributeConverter<String, String> {

    private static final String SYS_PROP_KEY = "cardlifecycle.encrypt.pass";
    private static final String ENCRYPT_PASS = resolveEncryptPass();

    @Override
    public String convertToDatabaseColumn(String attribute) {
        // Logika enkripcije
        return encrypt(attribute);
    }

    @Override
    public String convertToEntityAttribute(String dbData) {
        return decrypt(dbData);
    }

    private String encrypt(String attribute) {
        // Logika enkripcije
        var encryptor = new StandardPBEStringEncryptor();
        encryptor.setPassword(ENCRYPT_PASS); // Postavite lozinku
        return encryptor.encrypt(attribute);
    }
    private String decrypt(String dbData) {
        // Logika dekripcije
        var encryptor = new StandardPBEStringEncryptor();
        encryptor.setPassword(ENCRYPT_PASS); // Postavite lozinku
        return encryptor.decrypt(dbData);
    }

    private static String resolveEncryptPass() {
        String fromProp = System.getProperty(SYS_PROP_KEY);
        if (fromProp != null && !fromProp.isEmpty()) {
            return fromProp;
        }
        throw new IllegalStateException("Encryption password not configured. Set system property '" + SYS_PROP_KEY + "' via YAML bootstrap.");
    }

}

